tests.floyd:
for(int tt=0;tt<100;tt++){
    n=10;init();vector<tuple<int,int,ll>> edges;
    for(int u=1;u<=n;u++) for(int v=u+1;v<=n;v++) if(rng()%3==0){
        ll w=(int)(rng()%31)-15; d[u][v]=w;edges.push_back({u,v,w});
    }
    floyd();
    for(int st=1;st<=n;st++){
        vector<ll> b(n+1,INF);b[st]=0;
        for(int i=1;i<n;i++) for(auto [u,v,w]:edges) if(b[u]!=INF) b[v]=min(b[v],b[u]+w);
        for(int v=1;v<=n;v++) assert(d[st][v]==b[v]);
    }
}

tests.kruskal:
for(int tt=0;tt<150;tt++){
    int n=rng()%5+1,m=rng()%9;
    for(int q=1;q<=m;q++) e[q]={(int)(rng()%n+1),(int)(rng()%n+1),(int)(rng()%21)-10};
    ll best=LLONG_MAX;
    for(int mask=0;mask<(1<<m);mask++){
        if(__builtin_popcount((unsigned)mask)!=n-1) continue;
        vector<vector<int>> b(n+1);ll sum=0;
        for(int j=0;j<m;j++) if(mask>>j&1){auto [u,v,w]=e[j+1];b[u].push_back(v);b[v].push_back(u);sum+=w;}
        vector<int> seen(n+1),q={1};seen[1]=1;
        for(int i=0;i<(int)q.size();i++) for(int v:b[q[i]]) if(!seen[v]){seen[v]=1;q.push_back(v);}
        if((int)q.size()==n) best=min(best,sum);
    }
    auto [ok,w]=kruskal(n,m);assert(ok==(best!=LLONG_MAX));if(ok) assert(w==best);
}

tests.astar_kth_walk:
for(int tt=0;tt<150;tt++){
    n=6;for(int i=1;i<=n;i++){g1[i].clear();g2[i].clear();}
    for(int q=0;q<15;q++){int u=rng()%n+1,v=rng()%n+1;ll w=rng()%6;g1[u].push_back({v,w});g2[v].push_back({u,w});}
    s=rng()%n+1;t=rng()%n+1;k=rng()%5+1;int goal=k+(s==t);
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq;
    vector<int> count(n+1);pq.push({0,s});ll expected=-1;
    while(!pq.empty()){
        auto [d,u]=pq.top();pq.pop();if(++count[u]>goal)continue;
        if(u==t && count[u]==goal){expected=d;break;}
        for(auto [v,w]:g1[u])pq.push({d+w,v});
    }
    if(s==t)k++;
    dijkstra(t);Astar(s);assert(ans==expected);
}
